"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def longestUniqueSubstring(str):
    seen = {}
    maxLen = 0
    start = 0
    for i in range(0, len(str)):
        if ((str[i] in seen) and (seen[str[i]] >= start)):
            start = (seen[str[i]] + 1)
        seen[str[i]] = i
        maxLen = max(maxLen, ((i - start) + 1))
    return maxLen
print(longestUniqueSubstring('abcabcbb'))